$("loginform").addEventListener("submit",async e=>{e.preventDefault();try{const x=Object.fromEntries(new FormData(e.target));state.token=(await api("login",x)).token;state.method=await api("methodology");$("ai-draft").hidden=!state.method.modelEnabled;for(const n of ["Canonical TCI",...Object.keys(state.method.personaWeights)])$("persona").append(el("option",n));for(const d of state.method.documentGuide){const opt=el("option",d.title+" · "+d.id);opt.value=d.id;$("request").append(opt);}state.analysis=await api("analyze");const w=await api("workspace");state.answers=w.answers;state.reviews=w.reviews;state.edits=w.edits;state.snapshots=w.snapshots;$("snapshot-title").value=w.title;$("persona").value=w.persona;$("target").value=w.target??"";state.loaded=true;$("login").hidden=true;$("work").hidden=false;e.target.reset();for(const d of Object.keys(state.method.weights))$("dimension").append(el("option",d));renderFiles();renderQuestions();step(0,true);status("");}catch(err){status(err.message);}});
$("logout").onclick=async()=>{try{await saveWorkspace();await api("logout",{});}finally{location.reload();}};
