function renderFiles(){renderGuide();const a=state.analysis;$("filecount").textContent=a.files.length+" files";$("filelist").replaceChildren();for(const f of a.files){const d=el("div",undefined,"file");d.append(el("strong",f.name),el("p",f.format.toUpperCase()+" · "+f.segments+" extracted passages · format only; not malware scanned","muted"));const b=el("button","Inspect extracted source","secondary"),pre=el("pre",undefined,"source-preview");pre.hidden=true;b.onclick=async()=>{try{if(!pre.hidden){pre.hidden=true;return;}const source=await api("source",{digest:f.digest});pre.textContent=source.segments.map(x=>"["+x.location+"] "+x.text).join("\n");pre.hidden=false;}catch(e){status(e.message);}};d.append(b,pre);$("filelist").append(d);}const mapped=a.criteria.filter(c=>c.sources.length).length;$("coverage").replaceChildren(el("p",mapped+" of 28 criteria have candidate evidence. "+a.criteria.filter(c=>c.suggested!==null).length+" tentative anchor suggestions.","row"));}
$("dimension").onchange=renderQuestions;
