async function refresh(){if(state.result)return;const rev=state.revision;const result=await api("calculate",{rows:state.reviews,interviews:state.answers});if(rev!==state.revision)return;state.result=result;if(!state.actions)state.actions=mergePlan(result.actionPlan);}
function valueText(v){return v==null?"—":v.toFixed(2)+" / 5";}
function lens(){const p=$("persona").value,r=state.result;if(p==="Canonical TCI")return {reviewed:r?.draftScore,candidate:r?.unreviewedModelScore};return {reviewed:r?.personaScores[p]?.score,candidate:r?.personaScores[p]?.proposal};}
