async function saveWorkspace(){if(!state.loaded)return;const payload={answers:state.answers,reviews:state.reviews,edits:state.edits,title:$("snapshot-title").value,persona:$("persona").value,target:$("target").value?Number($("target").value):null};const w=await api("workspace",payload);state.snapshots=w.snapshots;}
